1	import { useEffect, useMemo, useState } from "react";
2	import { loadPackText, type Pack, an } from "@runlog/rules-schema";
3	import { listRuns, type StoredPack, type StoredRun } from "../storage/db.ts";
4	import { syncBus } from "../sync/bus.ts";
5	import { useSync } from "../sync/SyncProvider.tsx";
6	import { activeRunFor } from "../run/active.ts";
7	import { RunRow, onDay } from "../run/RunRow.tsx";
8	import { SetupShelf } from "./SetupShelf.tsx";
9	import { scoresOf } from "../run/scores.ts";
10	import { byLastOpened, openedAt } from "./opened.ts";
11	import { DocMenu } from "../docs/DocMenu.tsx";
12	import { HomeStrip } from "./HomeStrip.tsx";
13	import { PackServers } from "./PackServers.tsx";
14	import { useGuildVaults } from "./useGuildVaults.ts";
15	
16	/**
17	 * The library: your packs, newest-played first, each with its runs.
18	 *
19	 * One view that answers "what am I playing?". A pack is a card with its
20	 * runs beneath it, Continue on each, Start another, Forget, and the
21	 * order is what you played last on this device, so the pack you run most
22	 * nights is at the top with its open run one press away. Load-a-file lives
23	 * here too, and a pack of your own takes a newer file on its own row, its
24	 * runs kept. Nothing is a menu; everything is on the page.
25	 *
26	 * Nothing ships in it. The marketplace is where packs come from, and this view
27	 * is where the marketplace is reached from.
28	 */
29	
30	export interface LibraryPack {
31	  id: string;
32	  title: string;
33	  /** A line under the title: where it came from, its version. */
34	  sub: string;
35	  source: string;
36	  /** The stored record, for the packs that are yours; none for a built-in. */
37	  record?: StoredPack;
38	  /** The marketplace's newer version of this pack, when it has one. */
39	  update?: string;
40	  /** Whether this is the test bench pack. */
41	  bench?: boolean;
42	}
43	
44	const FALLBACK_VOCABULARY: Pack["vocabulary"] = {
45	  unit: { one: "Unit", many: "Units" },
46	  subject: { one: "Piece", many: "Pieces" },
47	  run: { one: "Run", many: "Runs" },
48	} as Pack["vocabulary"];
49	
50	export function LibraryView({
51	  packs,
52	  activeId,
53	  onOpen,
54	  onContinue,
55	  onStartAnother,
56	  onTest,
57	  onForgetRun,
58	  onForgetPack,
59	  onFile,
60	  onSyncToggle,
61	  onMarketplace,
62	  onUpdate,
63	  onReplace,
64	  onJoinRace,
65	  onContinueLast,
66	}: {
67	  packs: LibraryPack[];
68	  activeId: string;
69	  onOpen: (pack: LibraryPack) => void;
70	  onContinue: (pack: LibraryPack, run: StoredRun) => void;
71	  onStartAnother: (pack: LibraryPack) => void;
72	  /** Play it without keeping anything: to see how it goes, or to test it. */
73	  onTest?: (pack: LibraryPack) => void;
74	  onForgetRun: (run: StoredRun) => void;
75	  onForgetPack: (record: StoredPack) => void;
76	  onFile: (file: File | undefined) => void;
77	  onSyncToggle: (record: StoredPack, on: boolean) => void;
78	  onMarketplace: () => void;
79	  /** Take the marketplace's newer version of a pack. */
80	  onUpdate?: (record: StoredPack) => void;
81	  /** Take a newer file of a pack already here; its runs stay. Not for a sealed copy. */
82	  onReplace?: (record: StoredPack, file: File | undefined) => void;
83	  /** Join a race by its six-letter code; absent where nobody is signed in. */
84	  onJoinRace?: (code: string) => void;
85	  /** Open the run this account touched last, on this device or another. */
86	  onContinueLast?: (runId?: string) => void;
87	}) {
88	  const [raceCode, setRaceCode] = useState("");
89	  // Which servers may play what, read once for the shelf; empty where
90	  // there is no bot behind this copy or nobody signed in.
91	  const vaults = useGuildVaults();
92	  const sync = useSync();
93	  const [runs, setRuns] = useState<StoredRun[]>([]);
94	  const reload = () => void listRuns().then((all) => setRuns(all.filter((r) => !r.deletedAt)));
95	  useEffect(() => {
96	    reload();
97	    return syncBus.subscribe((news) => {
98	      if ((news.t === "localChange" || news.t === "pulled") && news.kind === "run") reload();
99	    });
100	  }, []);
101	
102	  const ordered = useMemo(() => byLastOpened(packs), [packs]);
103	
104	  /** Each pack, fully parsed, once per source: its words for the rows, and enough to score them. */
105	  const parsedPacks = useMemo(() => {
106	    const out = new Map<string, Pack>();
107	    for (const p of packs) {
108	      const parsed = loadPackText(p.source, p.record?.format ?? "yaml");
109	      if (parsed.ok) out.set(p.id, parsed.pack);
110	    }
111	    return out;
112	  }, [packs]);
113	
114	  const vocabularies = useMemo(() => {
115	    const out = new Map<string, Pack["vocabulary"]>();
116	    for (const p of packs) out.set(p.id, parsedPacks.get(p.id)?.vocabulary ?? FALLBACK_VOCABULARY);
117	    return out;
118	  }, [packs, parsedPacks]);
119	
120	  const runsOf = (packId: string) => runs.filter((r) => r.packId === packId).sort((a, b) => (a.updatedAt < b.updatedAt ? 1 : -1));
121	
122	  /** Score text for an ended run, by pack: a pack that failed to parse scores nothing. */
123	  const scoresByPack = useMemo(() => {
124	    const out = new Map<string, Map<string, string>>();
125	    for (const [id, pack] of parsedPacks) {
126	      out.set(id, new Map(scoresOf(pack, runsOf(id), Date.now()).map((s) => [s.runId, s.text])));
127	    }
128	    return out;
129	  }, [parsedPacks, runs]);
130	
131	  return (
132	    <main className="main library">
133	      <header className="libraryHead">
134	        <h2>Your packs</h2>
135	        <p className="muted">Newest played first. A pack's runs are beneath it; the one open on this device is marked.</p>
136	        <div className="libraryActions">
137	          <div className="libraryActionGroup">
138	            <h3 className="sectionTitle">Add a pack</h3>
139	            <div className="libraryActionGroupRow">
140	              <button className="primary" onClick={onMarketplace}>
141	                Get more packs
142	              </button>
143	              <label className="ghost fileButton">
144	                Load a pack from a file
145	                <input type="file" accept=".yaml,.yml,.json,.rlpack" onChange={(e) => onFile(e.target.files?.[0])} />
146	              </label>
147	            </div>
148	          </div>
149	          {onJoinRace && (
150	            <div className="libraryActionGroup">
151	              <h3 className="sectionTitle">Join a race</h3>
152	              <form
153	                className="raceJoin"
154	                onSubmit={(e) => {
155	                  e.preventDefault();
156	                  if (raceCode.trim().length >= 6) {
157	                    onJoinRace(raceCode.trim());
158	                    setRaceCode("");
159	                  }
160	                }}
161	              >
162	                <input
163	                  className="textInput code"
164	                  value={raceCode}
165	                  placeholder="race code"
166	                  maxLength={8}
167	                  aria-label="A race code, six letters"
168	                  onChange={(e) => setRaceCode(e.target.value.toUpperCase())}
169	                />
170	                <button className="ghost" type="submit" disabled={raceCode.trim().length < 6}>
171	                  Join a race
172	                </button>
173	              </form>
174	            </div>
175	          )}
176	        </div>
177	      </header>
178	
179	      <HomeStrip
180	        packs={ordered}
181	        runs={runs}
182	        vocabularies={vocabularies}
183	        onContinue={onContinue}
184	        onContinueLast={onContinueLast}
185	        onOpen={onOpen}
186	        onMarketplace={onMarketplace}
187	      />
188	
189	      {ordered.length === 0 && (
190	        <section className="panel">
191	          <p>No packs here yet. Pick one from the marketplace, or load one of your own from a file.</p>
192	        </section>
193	      )}
194	
195	      {ordered.map((p) => {
196	        const v = vocabularies.get(p.id) ?? FALLBACK_VOCABULARY;
197	        const mine = runsOf(p.id);
198	        const open = activeRunFor(p.id);
199	        const last = openedAt(p.id);
200	        const record = p.record;
201	        return (
202	          <section key={p.id} className={`panel libraryPack ${p.id === activeId ? "inPlay" : ""}`}>
203	            <div className="libraryPackHead">
204	              <button className="libraryTitle" onClick={() => onOpen(p)} title={`Open ${p.title}`}>
205	                <strong>{p.title}</strong>
206	                {p.bench && <span className="chip cap">test bench</span>}
207	                <span className="muted small">
208	                  {p.sub}
209	                  {last && ` · played ${onDay(last)}`}
210	                  {p.id === activeId && " · in play"}
211	                </span>
212	              </button>
213	              <div className="libraryPackActions">
214	                {record && p.update && onUpdate && (
215	                  <button
216	                    className="ghost tiny update"
217	                    onClick={() => onUpdate(record)}
218	                    title={`The marketplace has v${p.update}; your ${v.run.many.toLowerCase()} are kept`}
219	                  >
220	                    Update to v{p.update}
221	                  </button>
222	                )}
223	                <DocMenu compact pack={() => loadPackText(p.source, p.record?.format ?? "yaml").pack} at={{ section: "packs", id: p.id }} />
224	                {/*
225	                  The one thing anybody came here to do, and it looked
226	                  like the four things beside it. Documents, Test, Every
227	                  server, Replace and Forget are all errands; starting is
228	                  the point of a shelf of packs.
229	                */}
230	                <button className="primary tiny" onClick={() => onStartAnother(p)}>
231	                  {mine.length > 0 ? `Start another ${v.run.one.toLowerCase()}` : `Start ${an(v.run.one.toLowerCase())}`}
232	                </button>
233	                {onTest && (
234	                  <button
235	                    className="ghost tiny"
236	                    onClick={() => onTest(p)}
237	                    title={`Play ${p.title} in ${an(v.run.one.toLowerCase())} that is not saved`}
238	                  >
239	                    Test
240	                  </button>
241	                )}
242	                {/* Where this pack may be played, answered at the shelf
243	                    rather than from each server's own page. */}
244	                {record && <PackServers pack={record} vaults={vaults} />}
245	                {record && !record.sealed && onReplace && (
246	                  <label
247	                    className="ghost tiny fileButton"
248	                    title={`Load a newer file of ${p.title}; its ${v.run.many.toLowerCase()} are kept`}
249	                  >
250	                    Replace from a file
251	                    <input
252	                      type="file"
253	                      accept=".yaml,.yml,.json"
254	                      onChange={(e) => {
255	                        onReplace(record, e.target.files?.[0]);
256	                        // So the same file, fixed and chosen again, counts as a change.
257	                        e.target.value = "";
258	                      }}
259	                    />
260	                  </label>
261	                )}
262	                {record && (
263	                  <button
264	                    className="ghost tiny danger"
265	                    title={`Forget ${p.title} and its ${v.run.many.toLowerCase()}`}
266	                    onClick={() => onForgetPack(record)}
267	                  >
268	                    Forget pack
269	                  </button>
270	                )}
271	              </div>
272	            </div>
273	
274	            {mine.length > 0 && (
275	              <div className="runList">
276	                {mine.map((r) => (
277	                  <RunRow
278	                    key={r.runId}
279	                    run={r}
280	                    vocabulary={v}
281	                    open={r.runId === open && p.id === activeId}
282	                    score={scoresByPack.get(p.id)?.get(r.runId)}
283	                    onPick={() => onContinue(p, r)}
284	                    onForget={() => onForgetRun(r)}
285	                  />
286	                ))}
287	              </div>
288	            )}
289	
290	            {record &&
291	              sync.available &&
292	              (record.sealed ? (
293	                <p className="packSync muted">license key kept in your account; the text stays on this device</p>
294	              ) : (
295	                <label className="packSync" title="Its text is stored in your account and comes to your other devices">
296	                  <input type="checkbox" checked={record.sync === true} onChange={(e) => onSyncToggle(record, e.target.checked)} />
297	                  <span>keep this pack in sync</span>
298	                </label>
299	              ))}
300	          </section>
301	        );
302	      })}
303	
304	      {/*
305	        The other shelf. Under the packs because a pack is what a person
306	        comes here for; a setup is a thing that fits one, and nobody opens
307	        the library looking for one first.
308	      */}
309	      <SetupShelf />
310	    </main>
311	  );
312	}
