  id: "com.example.kiln",
  title: "Kiln Yard",
  version: "1.0.0",
  source,
  format: "yaml",
  filename: "kiln.yaml",
  importedAt: "2026-01-01T00:00:00Z",
  updatedAt: "2026-01-01T00:00:00Z",
  ...over,
});

const shelf = (records: StoredPack[]): LibraryPack[] =>
  records.map((r) => ({ id: r.id, title: r.title, sub: `from your file, v${r.version}`, source: r.source, record: r }));

const noop = () => {};
