// @vitest-environment jsdom
import { afterEach, describe, expect, it, vi } from "vitest";
import { cleanup, fireEvent, render, screen, within } from "@testing-library/react";
import { MarketplaceView } from "./MarketplaceView.tsx";
import type { MarketplaceEntry } from "./marketplace.ts";

/**
 * The marketplace card's footer, once owned and not.
 *
 * "In your packs · open" used to be one button: it read as a status until
 * you noticed it was pressable. Splitting it into a quiet chip and a real
 * "Open" button only holds up if the button still fires onOpen with the
 * right id, so that is what this exercises rather than the layout, which
 * the eye can check but a string match cannot.
 */

const ownedEntry: MarketplaceEntry = {
  id: "com.example.owned",
  version: "1.0.0",
  title: "Owned Pack",
  category: "everyday",
  tags: [],
  features: [],
  requires: [],
  players: 1,
  blurb: "everyday · solo",
  kind: "pack",
  price: "free",
  source: "bundled",
  load: async () => "",
};

const freeEntry: MarketplaceEntry = {
  id: "com.example.free",
  version: "1.0.0",
  title: "Free Pack",
  category: "everyday",
  tags: [],
  features: [],
  requires: [],
  players: 1,
  blurb: "everyday · solo",
  kind: "pack",
  price: "free",
  source: "bundled",
  load: async () => "",
};

const setupEntry: MarketplaceEntry = {
  id: "com.example.setup",
  version: "1.0.0",
  title: "A Loadout",
  category: "everyday",
  tags: [],
  features: [],
  requires: [],
  players: 1,
  blurb: "everyday · solo",
  kind: "setup",
  price: "free",
  source: "listing",
  load: async () => "",
};

vi.mock("./marketplace.ts", async (importOriginal) => {
  const actual = await importOriginal<typeof import("./marketplace.ts")>();
  return { ...actual, loadMarketplace: vi.fn(async () => [ownedEntry, freeEntry, setupEntry]) };
});

afterEach(cleanup);

describe("the marketplace card's footer", () => {
  it("shows an owned pack as a quiet chip plus an Open button that calls onOpen with its id", async () => {
    const onOpen = vi.fn();
    render(<MarketplaceView mine={new Set([ownedEntry.id])} onAdd={async () => {}} onOpen={onOpen} onBack={() => {}} />);

    const card = (await screen.findByText("Owned Pack")).closest("article");
    if (!card) throw new Error("no card rendered for the owned pack");
    expect(within(card).getByText("In your packs")).toBeTruthy();
    // The paper is one button, Docs, which opens the drawer on the summary; nothing unfolds in the card.
    expect(within(card).getByRole("button", { name: "Docs" })).toBeTruthy();
    expect(within(card).queryByText("Documents")).toBeNull();
    const openButton = within(card).getByRole("button", { name: "Open" });

    fireEvent.click(openButton);
    expect(onOpen).toHaveBeenCalledWith(ownedEntry.id);
  });

  it("offers a free, unowned pack with Add to my packs", async () => {
    render(<MarketplaceView mine={new Set()} onAdd={async () => {}} onOpen={() => {}} onBack={() => {}} />);

    const card = (await screen.findByText("Free Pack")).closest("article");
    if (!card) throw new Error("no card rendered for the free pack");
    expect(within(card).getByRole("button", { name: "Add to my packs" })).toBeTruthy();
    expect(within(card).queryByText("In your packs")).toBeNull();
  });

  it("offers a deck to a pack and not to a setup", async () => {
    // A setup is what a tool is set to while a run lasts. It has no moves,
    // no counters and no resources, so there is nothing to lay out on keys.
    render(<MarketplaceView mine={new Set()} onAdd={async () => {}} onOpen={() => {}} onBack={() => {}} />);

    const pack = (await screen.findByText("Free Pack")).closest("article");
    expect(within(pack!).getByText("Stream Deck profile")).toBeTruthy();

    fireEvent.click(screen.getByRole("button", { name: /Setups/ }));
    const setup = (await screen.findByText("A Loadout")).closest("article");
    expect(within(setup!).queryByText("Stream Deck profile")).toBeNull();
  });
});

